//! DataList connection retains real node, Attr and collection identity.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><div id=target>Fallback<datalist id=datalist title=seed></datalist><span id=tail>tail</span></div><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://datalist-connection.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]fn datalist_connection_created_append_reorder_remove_preserves_collection(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var target=document.getElementById('target'),first=target.firstChild,x=document.createElement('datalist');x.setAttribute('title','native');var attr=x.getAttributeNode('title'),list=x.options;target.appendChild(x);if(x.parentNode!==target||x.ownerDocument!==document||target.lastChild!==x||x.getAttributeNode('title')!==attr||x.options!==list||list.length!==0)throw 'created DataList connection';target.insertBefore(x,first);if(target.firstChild!==x||x.nextSibling!==first||attr.ownerElement!==x||x.options!==list)throw 'DataList reorder';target.removeChild(x);if(x.parentNode!==null||target.firstChild!==first||x.getAttribute('title')!=='native'||x.getAttributeNode('title')!==attr||x.options!==list||document.getElementById('neighbor').value!=='seed')throw 'DataList removal';
"#);}
#[test]fn datalist_connection_inert_insert_preserves_node_attr_owner_and_same_object(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var target=document.getElementById('target'),tail=document.getElementById('tail'),owner=new Document(),x=owner.createElementNS('http://www.w3.org/1999/xhtml','datalist');x.setAttribute('title','A\udfffZ');var attr=x.getAttributeNode('title'),list=x.options;target.insertBefore(x,tail);if(!(x instanceof HTMLDataListElement)||x.parentNode!==target||x.nextSibling!==tail||x.ownerDocument!==document||attr.ownerDocument!==document||attr.ownerElement!==x||x.getAttributeNode('title')!==attr||x.getAttribute('title')!=='A\udfffZ'||x.options!==list||list.length!==0)throw 'inert DataList owner transfer';target.removeChild(x);if(x.ownerDocument!==document||x.parentNode!==null||attr.ownerDocument!==document||x.options!==list)throw 'transferred removal';
"#);}
#[test]fn datalist_connection_native_clone_template_parking_roundtrip_keeps_identity(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var target=document.getElementById('target'),source=document.getElementById('datalist'),x=source.cloneNode(false),attr=x.getAttributeNode('title'),list=x.options,template=document.createElement('template');template.content.appendChild(x);if(x.parentNode!==template.content||x.ownerDocument!==template.content.ownerDocument||attr.ownerDocument!==x.ownerDocument||x.getAttributeNode('title')!==attr||x.getAttribute('title')!=='seed'||x.options!==list)throw 'DataList native parking';target.appendChild(template.content);if(x.parentNode!==target||x.ownerDocument!==document||attr.ownerDocument!==document||x.getAttributeNode('title')!==attr||template.content.firstChild!==null||source.getAttribute('title')!=='seed'||x.options!==list||list.length!==0)throw 'DataList parking roundtrip';
"#);}

#[test]
fn datalist_connection_storage_work_copy_and_deadline_refusals_preserve_identity_and_recover(){
 for parking in [false,true]{for mode in 0..4{
  let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if parking{
   "var target=document.createElement('template').content,source=document.getElementById('datalist').cloneNode(false);"
  }else{
   "var target=document.getElementById('target'),owner=new Document(),source=owner.createElementNS('http://www.w3.org/1999/xhtml','datalist');"
  });
  run(&mut d,&mut f,&mut p,"source.setAttribute('title','retained');var list=source.options,attr=source.getAttributeNode('title'),watch=new MutationObserver(function(){});watch.observe(target,{childList:true});var originalOwner=source.ownerDocument;");
  p.state.rebuild(&d).unwrap();let tree=format!("{:?}",d.nodes);
  let before=(p.state.retained,p.state.dom_commits,p.state.inert_documents.backing_bytes(),Bridge{doc: &mut d,forms: &mut f,state: &mut p.state}.inert_node_count(),p.state.attributes.len(),p.state.detached_nodes.clone());
  let limit=p.state.retained_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())};
  let error=p.runtime.execute("target.appendChild(source);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();
  assert!(error.contains("work")||error.contains("allowance")||error.contains("limit")||error.contains("bound")||error.contains("time"),"{parking}/{mode}: {error}");
  assert_eq!(format!("{:?}",d.nodes),tree);assert_eq!((p.state.retained,p.state.dom_commits,p.state.inert_documents.backing_bytes(),Bridge{doc: &mut d,forms: &mut f,state: &mut p.state}.inert_node_count(),p.state.attributes.len(),p.state.detached_nodes.clone()),before);
  p.state.retained_limit=limit;p.state.execution_deadline=None;p.begin_job();
  run(&mut d,&mut f,&mut p,"if(source.parentNode!==null||source.ownerDocument!==originalOwner||source.getAttributeNode('title')!==attr||attr.ownerElement!==source||source.getAttribute('title')!=='retained'||source.options!==list||watch.takeRecords().length)throw 'atomic DataList transfer refusal';target.appendChild(source);var records=watch.takeRecords();if(source.parentNode!==target||source.ownerDocument!==target.ownerDocument||attr.ownerDocument!==target.ownerDocument||source.getAttributeNode('title')!==attr||source.getAttribute('title')!=='retained'||source.options!==list||records.length!==1)throw 'fresh DataList transfer recovery '+[source.parentNode===target,source.ownerDocument===target.ownerDocument,attr.ownerDocument===target.ownerDocument,source.getAttributeNode('title')===attr,records.length].join(',');");
  assert!(!p.has_navigation_request());assert!(p.take_dynamic_scripts().is_empty()&&p.take_dynamic_stylesheets().is_empty());assert!(!p.state.images.has_changes());
 }}
}

#[test]
fn datalist_connection_saved_child_append_revalidates_origin_before_transferring_owner(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var owner=new Document(),source=owner.createElementNS('http://www.w3.org/1999/xhtml','datalist'),target=document.getElementById('target'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);source.setAttribute('title','saved');var list=source.options,saved=frame.contentWindow.Node.prototype.appendChild,attr=source.getAttributeNode('title');");
 p.set_location(&crate::navigation::address("https://other-datalist.test/",&crate::navigation::Location::home()).unwrap());
 let tree=format!("{:?}",d.nodes);let before=(p.state.retained,p.state.dom_commits);p.begin_job();
 let error=p.runtime.execute("saved.call(target,source);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");
 assert_eq!(format!("{:?}",d.nodes),tree);assert_eq!((p.state.retained,p.state.dom_commits),before);
 p.set_location(&crate::navigation::address("https://datalist-connection.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();
 run(&mut d,&mut f,&mut p,"if(source.parentNode!==null||source.ownerDocument!==owner||attr.ownerDocument!==owner||source.getAttribute('title')!=='saved'||source.options!==list)throw 'denied transfer preserves owner';if(saved.call(target,source)!==source||source.ownerDocument!==document||source.parentNode!==target||source.getAttributeNode('title')!==attr||attr.ownerDocument!==document||source.getAttribute('title')!=='saved'||source.options!==list)throw 'saved transfer fresh recovery';");
}



#[test]fn datalist_connection_parsed_and_fragment_clones_roundtrip_with_separate_collections(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var target=document.getElementById('target'),template=document.createElement('template');template.innerHTML='<datalist title="parsed"></datalist>';var fragment=template.content,parsed=fragment.firstChild,attr=parsed.getAttributeNode('title'),list=parsed.options,donor=fragment.cloneNode(true),cloned=donor.firstChild,other=cloned.options;target.appendChild(fragment);target.appendChild(donor);if(fragment.firstChild!==null||donor.firstChild!==null||parsed===cloned||parsed.parentNode!==target||cloned.parentNode!==target||parsed.ownerDocument!==document||cloned.ownerDocument!==document||parsed.getAttributeNode('title')!==attr||attr.ownerDocument!==document||cloned.getAttribute('title')!=='parsed'||parsed.options!==list||cloned.options!==other||list===other||list.length||other.length)throw 'parsed DataList identity and separate collections';
"#);assert!(!p.has_navigation_request());assert!(p.take_dynamic_scripts().is_empty()&&p.take_dynamic_stylesheets().is_empty());assert!(!p.state.images.has_changes());}
#[test]fn datalist_connection_active_foreign_and_nonleaf_parking_refuse_atomically(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var target=document.getElementById('target'),template=document.createElement('template');template.innerHTML='<datalist title="held" onclick="return 1;"></datalist>';var source=template.content.firstChild,owner=source.ownerDocument,attr=source.getAttributeNode('title'),list=source.options,watch=new MutationObserver(function(){});watch.observe(target,{childList:true});var caught=false;try{target.appendChild(source);}catch(e){caught=e instanceof DOMException&&e.name==='NotSupportedError';}if(!caught||source.parentNode!==template.content||source.ownerDocument!==owner||attr.ownerDocument!==owner||source.getAttributeNode('title')!==attr||source.options!==list||watch.takeRecords().length)throw 'active transfer refusal';var foreign=owner.createElementNS('urn:other','datalist');caught=false;try{target.appendChild(foreign);}catch(e){caught=e instanceof DOMException&&e.name==='NotSupportedError';}if(!caught||foreign.parentNode!==null||foreign.ownerDocument!==owner||watch.takeRecords().length)throw 'foreign transfer refusal';var clean=owner.createElementNS('http://www.w3.org/1999/xhtml','datalist');clean.setAttribute('title','safe');var cleanList=clean.options;target.appendChild(clean);if(clean.ownerDocument!==document||clean.getAttribute('title')!=='safe'||clean.options!==cleanList||watch.takeRecords().length!==1)throw 'safe fresh recovery';var data=new Document(),raw=data.createElementNS('http://www.w3.org/1999/xhtml','datalist');raw.appendChild(data.createTextNode('held'));var nonleaf=document.importNode(raw,true);caught=false;try{document.createElement('template').content.appendChild(nonleaf);}catch(e){caught=e instanceof DOMException&&e.name==='NotSupportedError';}if(!caught||nonleaf.parentNode!==null||nonleaf.textContent!=='held')throw 'nonleaf parking remains guarded';
"#);assert!(!p.has_navigation_request());assert!(p.take_dynamic_scripts().is_empty()&&p.take_dynamic_stylesheets().is_empty());assert!(!p.state.images.has_changes());}
